return ['domain'=>'presspermit-pro&& n%100<=10 ? 3 : n%100>=11 ? 4 : 5;','plural-forms'=>'nplurals=6; plural=(n == 0 ? 0 : n == 1 ? 1 : n == 2 ? 2 : n % 100 >= 3 && n % 100 <= 10 ? 3 : n % 100 >= 11 ? 4 : 5);','language'=>'ar% 100 >= 3 && n % 100 <= 10 ? 3: n % 100 >= 11 ? 4 : 5);','project-id-version'=>'PublishPress Permissions Pro 4.8.1','pot-creation-date'=>'2026-04-02T18:54:49+00:00','po-revision-date'=>'2026-10-01 19:50+0000','x-generator'=>'Weblate 2026.6.1','messages'=>['PublishPress Permissions Pro'=>'نشرPress أذونات برو','https://publishpress.com/permissions'=>'https://publishpress.com/permissions','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'تتيح لك صلاحيات PublishPress تمكين أو رفض الوصول إلى المشاركات، الصفحات، الفئات، العلامات والمزيد.','PublishPress'=>'نشرPress','https://publishpress.com/'=>'https://publishpress.com/','Should pages with privacy status "premium" require set_pages_premium and edit_premium_pages capabilities? If so, you can %1$sassign a status-specific Page Editor role%2$s or %3$sadd the capabilities directly to a role%4$s.'=>'هل يجب أن تتطلب الصفحات ذات حالة الخصوصية "مميزة" قدرات set_pages_premium و edit_premium_pages؟ إذا كان الأمر كذلك، يمكنك %1$sتعيين دور محرر صفحة خاص بالحالة%2$s أو %3$sإضافة القدرات مباشرة إلى دور%4$s.','Note: Workflow sequence and branching for pre-publication is configured %son a separate screen%s'=>'ملاحظة: يتم تكوين تسلسل سير العمل والتفرع قبل النشر %son a separate screen%s','Additional settings provided by the %s module.'=>'الإعدادات الإضافية المقدمة بواسطة وحدة %s.','Note: If you deactive, re-entry of the license key will be required for re-activation.'=>'ملاحظة: إذا قمت بإلغاء التنشيط، ستكون هناك حاجة لإعادة إدخال مفتاح الترخيص للتفعيل مرة أخرى.','If enabled, custom group membership is applied network-wide (though role assignments are still site-specific).'=>'إذا تم تمكينه، يتم تطبيق عضوية المجموعة المخصصة على مستوى الشبكة (على الرغم من أن تعيين الأدوار لا يزال خاصًا بالموقع).','Can create network-wide permission groups'=>'يمكن إنشاء مجموعات أذونات على مستوى الشبكة','If group editing is allowed, can also modify network group membership'=>'إذا كان تحرير المجموعة مسموحًا به، يمكن أيضًا تعديل عضوية المجموعة الشبكية','This feature will control direct URL access to files in /uploads/ folder. By default, files are blocked if they are attached to a post which the user can\'t view.'=>'ستتحكم هذه الميزة في الوصول المباشر إلى الملفات في مجلد /uploads/. بشكل افتراضي، يتم حظر الملفات إذا كانت مرتبطة بمشاركة لا يمكن للمستخدم رؤيتها.','File Access on multisite installations will require the following rules to be inserted above the stock ms-files.php rules in the %1$smain .htaccess file%2$s:'=>'سيتطلب الوصول إلى الملفات في التثبيتات متعددة المواقع إدخال القواعد التالية فوق قواعد ms-files.php الافتراضية في %1$smain .htaccess file%2$s:','But your .htaccess is missing or not writeable!'=>'لكن ملف .htaccess الخاص بك مفقود أو غير قابل للكتابة!','.htaccess needs to be updated to include these rules.'=>'يجب تحديث ملف .htaccess ليشمل هذه القواعد.','.htaccess file has all required rules.'=>'يحتوي ملف .htaccess على جميع القواعد المطلوبة.','These rules will not be inserted automatically.  You are responsible for editing .htaccess and later removing the rules if the functionality is no longer desired.'=>'لن يتم إدخال هذه القواعد تلقائيًا. أنت مسؤول عن تحرير .htaccess وإزالة القواعد لاحقًا إذا لم تعد الوظيفة مرغوبة.','Note that an additional rule will need to be added with each new site. %1$sTo eliminate this requirement, research "WordPress remove ms-files".%2$s'=>'لاحظ أنه ستحتاج إلى إضافة قاعدة إضافية مع كل موقع جديد. %1$sلإزالة هذا الشرط، ابحث عن "إزالة ms-files ووردبريس".%2$s','You will need to manually restore the .htacces file to default contents if anything goes wrong. Proceed?'=>'ستحتاج إلى استعادة ملف .htaccess يدويًا إلى محتوياته الافتراضية إذا حدث أي خطأ. هل تريد المتابعة؟','Update .htaccess now'=>'تحديث .htaccess الآن','only for sites with protected files'=>'فقط للمواقع التي تحتوي على ملفات محمية','for all sites'=>'لكل المواقع','NONE: remove Permissions rules'=>'لا شيء: إزالة قواعد الأذونات','Since the plugin is not network-activated, you will need to modify the .htaccess file manually, inserting a RewriteRule as shown above for each site which needs file filtering.'=>'نظرًا لأن المكون الإضافي غير مفعل على الشبكة، ستحتاج إلى تعديل ملف .htaccess يدويًا، وإدخال RewriteRule كما هو موضح أعلاه لكل موقع يحتاج إلى تصفية الملفات.','This extends the File Access feature to files that are not attached to any post. This will not apply to user who have the edit_private_files or pp_list_all_files capability.'=>'تمتد هذه الميزة إلى الوصول إلى الملفات التي لا ترتبط بأي مشاركة. لن ينطبق هذا على المستخدمين الذين لديهم قدرة edit_private_files أو pp_list_all_files.','Make attached files unreadable to users who do not have the edit_private_files or pp_list_all_files capability.'=>'اجعل الملفات المرفقة غير قابلة للقراءة للمستخدمين الذين ليس لديهم قدرة edit_private_files أو pp_list_all_files.','Improve Media Library performance by disabling file filtering for thumbnails (size specified in Settings > Media).'=>'حسن أداء مكتبة الوسائط عن طريق تعطيل تصفية الملفات للصور المصغرة (الحجم المحدد في الإعدادات > الوسائط).','On some sites, an additional redirect is required to correctly deliver protected files. Leave this disabled for better performance if possible.'=>'في بعض المواقع، مطلوب إعادة توجيه إضافية لتسليم الملفات المحمية بشكل صحيح. اترك هذا معطلاً للحصول على أداء أفضل إذا كان ذلك ممكنًا.','The File Access feature uses an %1$s.htaccess%2$s file located at %3$suploads/.htaccess%4$s. Normally no action is needed, but clicking the button below will update the URL keys (at next site access) that protect the files.'=>'تستخدم ميزة الوصول إلى الملفات ملف %1$s.htaccess%2$s الموجود في %3$suploads/.htaccess%4$s. عادةً لا حاجة لأي إجراء، ولكن النقر على الزر أدناه سيقوم بتحديث مفاتيح URL (عند الوصول إلى الموقع التالي) التي تحمي الملفات.','The File Access feature uses an %1$s.htaccess%2$s file located at %3$suploads/.htaccess%4$s. Normally no action is needed, but clicking the button below will update the URL keys that protect the files.'=>'تستخدم ميزة الوصول إلى الملفات ملف %1$s.htaccess%2$s الموجود في %3$suploads/.htaccess%4$s. عادةً لا حاجة لأي إجراء، ولكن النقر على الزر أدناه سيقوم بتحديث مفاتيح URL التي تحمي الملفات.','Best practice is to access the above url periodically (using your own cron service) to prevent long-term bookmarking of protected files.'=>'أفضل ممارسة هي الوصول إلى عنوان URL أعلاه بشكل دوري (باستخدام خدمة cron الخاصة بك) لمنع وضع إشارة مرجعية طويلة الأجل على الملفات المحمية.','Supply a custom key which will enable a support url to regenerate file access keys.  Then execute the url regularly (using your own cron service) to prevent long-term bookmarking of protected files.'=>'قدم مفتاحًا مخصصًا والذي سيمكن عنوان URL للدعم من إعادة توليد مفاتيح وصول الملفات. ثم قم بتشغيل عنوان URL بانتظام (باستخدام خدمة cron الخاصة بك) لمنع وضع إشارة مرجعية طويلة الأجل على الملفات المحمية.','File Access can also protect files uploaded by FTP or other manual file copy, but does not detect them automatically. Click the button below to scan your uploads folder for files to protect.'=>'يمكن أن تحمي ميزة الوصول إلى الملفات أيضًا الملفات التي تم تحميلها عبر FTP أو نسخ الملفات يدويًا، ولكنها لا تكتشفها تلقائيًا. انقر على الزر أدناه لفحص مجلد التحميلات الخاص بك للبحث عن الملفات التي تحتاج إلى حماية.','Invalid file filtering key argument.'=>'وسيط مفتاح تصفية الملفات غير صالح.','Please configure File Access options!'=>'يرجى تكوين خيارات الوصول إلى الملفات!','The wp-content folder cannot be relocated outside the main WordPress folder.'=>'لا يمكن نقل مجلد wp-content خارج مجلد ووردبريس الرئيسي.','Files linked in post content must be in %1$s (or a subfolder of it). If you move files, consider using a %2$s search and replace plugin%3$s to update those URLs.'=>'يجب أن تكون الملفات المرتبطة بمحتوى المنشور في %1$s (أو مجلد فرعي له). إذا قمت بنقل الملفات، فكر في استخدام %2$s ملحق بحث واستبدال%3$s لتحديث تلك الروابط.','File Access can also protect files uploaded by FTP or other manual processes, but does not detect them automatically. This utility can find and protect any uploaded files.'=>'يمكن أن يحمي الوصول إلى الملفات الملفات التي تم رفعها عبر FTP أو عمليات يدوية أخرى، ولكنه لا يكتشفها تلقائيًا. يمكن لهذه الأداة العثور على أي ملفات تم رفعها وحمايتها.','To run this utility by cron task or other direct request, use the following URL:'=>'لتشغيل هذه الأداة بواسطة مهمة كرون أو طلب مباشر آخر، استخدم عنوان URL التالي:','To run this utility by direct URL, set a file filtering regen key on Permissions Settings'=>'لتشغيل هذه الأداة بواسطة عنوان URL مباشر، قم بتعيين مفتاح تجديد تصفية الملفات في إعدادات الأذونات','Note: Direct access to uploaded file attachments cannot be filtered because your WP_CONTENT_DIR is not in the WordPress branch.'=>'ملاحظة: لا يمكن تصفية الوصول المباشر إلى مرفقات الملفات التي تم رفعها لأن WP_CONTENT_DIR الخاص بك ليس في فرع ووردبريس.','The operation was terminated due to an invalid configuration.'=>'تم إنهاء العملية بسبب تكوين غير صالح.','Checking %s posts / pages...'=>'جاري فحص %s منشورات / صفحات...','%1$s skipping unfilterable file in %2$s "%3$s":%4$s %5$s'=>'%1$s يتجاوز ملف غير قابل للتصفية في %2$s "%3$s":%4$s %5$s','%1$s skipping missing file in %2$s "%3$s":%4$s %5$s'=>'%1$s يتجاوز ملف مفقود في %2$s "%3$s":%4$s %5$s','%1$sNew attachment in %2$s "%3$s":%4$s %5$s'=>'%1$sمرفق جديد في %2$s "%3$s":%4$s %5$s','%s linked uploads were found in your post / page content.'=>'تم العثور على %s تحميلات مرتبطة في محتوى منشورك / صفحتك.','%s attachment records were added to the database.'=>'تمت إضافة %s سجلات مرفقات إلى قاعدة البيانات.','All linked uploads are already registered as attachments.'=>'تم تسجيل جميع التحميلات المرتبطة كمرفقات بالفعل.','Statuses enabled here are available as Visibility options for post publishing. Affected posts become inaccessable without a corresponding status-specific role assignment.'=>'الحالات المفعلة هنا متاحة كخيارات رؤية لنشر المنشورات. تصبح المنشورات المتأثرة غير قابلة للوصول بدون تعيين دور محدد يتناسب مع الحالة.','Statuses enabled here are available in the editor as additional steps between Draft and Published.'=>'الحالات المفعلة هنا متاحة في المحرر كخطوات إضافية بين المسودة والمنشور.','Statuses alter your content\'s accessibility by imposing additional capability requirements.'=>'تغير الحالات إمكانية وصول محتواك عن طريق فرض متطلبات إضافية للقدرة.','Enable Custom Capabilities by toggling the link below status name. If enabled, non-Editors will need a corresponding %ssupplemental role%s to edit posts of that status.'=>'قم بتمكين القدرات المخصصة عن طريق تغيير الرابط أدناه اسم الحالة. إذا تم تمكينها، سيحتاج غير المحررين إلى دور مكمل متناسب %ssupplemental role%s لتحرير منشورات تلك الحالة.','For post edit by a user who cannot publish, %sworkflow is configured%s to make the Publish button increment the post to the next workflow status permitted.'=>'لتحرير المنشور بواسطة مستخدم لا يمكنه النشر، تم تكوين %sworkflow%s لجعل زر النشر يزيد المنشور إلى الحالة التالية المسموح بها في سير العمل.','For post edit by a user who cannot publish, %sworkflow is configured%s to make the Publish button escalate the post to the highest-ordered workflow status permitted.'=>'لتحرير المنشور بواسطة مستخدم لا يمكنه النشر، تم تكوين %sworkflow%s لجعل زر النشر يرفع المنشور إلى أعلى حالة مسموح بها في سير العمل.','For post edit by a user who cannot publish, the Publish button will escalate the post to the highest-order status permitted to the user.'=>'لتحرير المنشور بواسطة مستخدم لا يمكنه النشر، سيقوم زر النشر برفع المنشور إلى أعلى حالة مسموح بها للمستخدم.','Please enable the PublishPress %sStatuses feature%s.'=>'يرجى تمكين ميزة PublishPress %sالحالات%s.','Note that the Post Type itself will also need to have %sPermissions%s enabled.'=>'لاحظ أن نوع المنشور نفسه سيحتاج أيضًا إلى تمكين %sPermissions%s.','To disable custom visibility statuses, first re-assign posts to a different status.'=>'لإلغاء تفعيل حالات الرؤية المخصصة، أعيد تعيين المنشورات أولاً إلى حالة مختلفة.','Note, this only applies if the role definition includes the pp_moderate_any capability'=>'ملاحظة، هذا ينطبق فقط إذا كانت تعريفات الأدوار تشمل القدرة pp_moderate_any','Create or edit custom Privacy or Workflow statuses.'=>'إنشاء أو تعديل حالات الخصوصية أو سير العمل المخصصة.','Create or edit custom Privacy statuses.'=>'إنشاء أو تعديل حالات الخصوصية المخصصة.','Extra Roles created as a type-specific copy of this role will enable assignment of specified custom statuses.'=>'ستسمح الأدوار الإضافية التي تم إنشاؤها كنسخة مخصصة من هذا الدور بتعيين حالات مخصصة محددة.','Editors do not need status-specific editing capabilities for workflow posts (Assigned, In Progress, Approved).'=>'لا يحتاج المحررون إلى قدرات تحرير محددة للحالات لمنشورات سير العمل (مخصص، قيد التقدم، معتمد).','If enabled, non-Editors will need to be granted editing access via the "Permissions" screen.'=>'إذا تم تمكينها، سيحتاج غير المحررين إلى منحهم حق الوصول للتحرير عبر شاشة "الأذونات".','If enabled, a Visibility Status dropdown will appear in Quick Edit for easy status assignment.'=>'إذا تم تمكينها، سيظهر قائمة منسدلة لحالة الرؤية في التحرير السريع لتعيين الحالة بسهولة.','If enabled, this will add Visibility Statuses support to the PublishPress Status plugin.'=>'إذا تم تمكينها، سيضيف هذا دعم حالات الرؤية إلى ملحق PublishPress Status.','Post property or meta field to match with user field'=>'خاصية المنشور أو حقل البيانات الوصفية للتطابق مع حقل المستخدم','User property or meta field to match with post field'=>'خاصية المستخدم أو حقل البيانات الوصفية للتطابق مع حقل المنشور','User meta field to match with post field'=>'حقل بيانات وصفية للمستخدم للتطابق مع حقل المنشور','User role to include in synchronization'=>'دور المستخدم الذي يجب تضمينه في المزامنة','Parent id for created posts'=>'معرف الوالد للمنشورات التي تم إنشاؤها','Choose post field from suggested meta key names'=>'اختر حقل المنشور من أسماء المفاتيح الوصفية المقترحة','When a new user of specified role is added, create or designate a post for them.'=>'عند إضافة مستخدم جديد من الدور المحدد، قم بإنشاء أو تعيين منشور لهم.','Create or designate a post for existing users.'=>'إنشاء أو تعيين منشور للمستخدمين الحاليين.','This post type is not hierarchical'=>'نوع المنشور هذا ليس هرمياً','Automatically create a post for each user in selected roles.'=>'إنشاء منشور تلقائيًا لكل مستخدم في الأدوار المحددة.','Hint: If %s have custom fields (like email address), create one to assist field name discovery.'=>'تلميح: إذا كان لدى %s حقول مخصصة (مثل عنوان البريد الإلكتروني)، قم بإنشاء واحدة للمساعدة في اكتشاف أسماء الحقول.','Enable each user to edit their own User Posts.'=>'تمكين كل مستخدم من تحرير منشورات المستخدم الخاصة بهم.','Settings for replacing unreadable content with teaser text, provided by the %s module.'=>'إعدادات استبدال المحتوى غير القابل للقراءة بنص ترويجي، مقدمة من وحدة %s.','Settings on this tab do not apply because teaser filtering is disabled for all post types.'=>'لا تنطبق الإعدادات في هذه التبويب لأن تصفية الترويج معطلة لجميع أنواع المنشورات.','Since some browsers will cache feeds without regard to user login, block RSS content even for qualified users.'=>'نظرًا لأن بعض المتصفحات ستخزن المحتوى في الذاكرة المؤقتة دون النظر إلى تسجيل دخول المستخدم، قم بحظر محتوى RSS حتى للمستخدمين المؤهلين.','This feature controls what users will see when trying to view content they are blocked from accessing.'=>'تتحكم هذه الميزة فيما سيراه المستخدمون عند محاولة عرض المحتوى الذي تم حظرهم من الوصول إليه.','These settings adjust which views, link types and visibility statuses the teaser is applied to.'=>'تعدل هذه الإعدادات أي العروض، وأنواع الروابط، وحالات الرؤية التي يتم تطبيق الترويج عليها.','You can override Teaser settings within the Nav Menu by hiding links to unreadable posts that are associated with the terms you select below.'=>'يمكنك تجاوز إعدادات الترويج ضمن قائمة التنقل عن طريق إخفاء الروابط للمنشورات غير القابلة للقراءة المرتبطة بالشروط التي تحددها أدناه.','Keep unreadable content hidden in the blogroll and link lists, but show the teaser on direct access attempts.'=>'احتفظ بالمحتوى غير القابل للقراءة مخفيًا في قائمة المدونة وقوائم الروابط، ولكن اعرض النص الترويجي عند محاولات الوصول المباشر.','Hide unreadable private posts, but show a teaser for posts which are unreadable due to regular Privacy or Role Restrictions.'=>'اخفِ المنشورات الخاصة غير القابلة للقراءة، ولكن اعرض نصًا ترويجيًا للمنشورات التي لا يمكن قراءتها بسبب قيود الخصوصية أو قيود الدور العادية.','If anyone tries to view a post they don\'t have access to, redirect to another post instead of displaying a teaser.'=>'إذا حاول أي شخص عرض منشور ليس لديه وصول إليه، قم بإعادة التوجيه إلى منشور آخر بدلاً من عرض نص ترويجي.','Replace post content or excerpt with custom text, possibly including an inline login form. You can also add text before or after the post title and excerpt.'=>'استبدل محتوى المنشور أو مقتطفه بنص مخصص، قد يتضمن نموذج تسجيل دخول مضمن. يمكنك أيضًا إضافة نص قبل أو بعد عنوان المنشور ومقتطفه.','Unreadable items of these comma-separated types will have nav menu item hidden.'=>'ستكون العناصر غير القابلة للقراءة من هذه الأنواع المفصولة بفواصل مخفية في عنصر قائمة التنقل.','Visibility Circle membership does not limit viewing access.'=>'عضوية دائرة الرؤية لا تحد من إمكانية الوصول للمشاهدة.','Editorial Circle membership does not limit editing access.'=>'عضوية دائرة التحرير لا تحد من إمكانية الوصول للتحرير.','When searching for users via Permissions ajax, return return only users registered to current site'=>'عند البحث عن مستخدمين عبر Ajax الأذونات، قم بإرجاع المستخدمين المسجلين فقط في الموقع الحالي','If user is a super admin or has \'pp_manage_network_members\' capability, user searches via Permissions ajax return users from all sites'=>'إذا كان المستخدم مسؤولًا فائقًا أو لديه القدرة على \'pp_manage_network_members\'، فإن بحث المستخدمين عبر Ajax الأذونات يعيد المستخدمين من جميع المواقع','Count users as a member of a BuddyPress Permissions Group only if they are a moderator of the BP group'=>'اعتبر المستخدمين أعضاءً في مجموعة أذونات BuddyPress فقط إذا كانوا مشرفين على مجموعة BP','Count users as a member of a BuddyPress Permissions Group only if they are an administrator of the BP group'=>'اعتبر المستخدمين أعضاءً في مجموعة أذونات BuddyPress فقط إذا كانوا مدراء على مجموعة BP','CMS Page Tree View plugin: hide \'add\' links (for all hierarchical post types) based on user\'s association permissions'=>'مكون إضافي لعرض شجرة صفحات CMS: إخفاء روابط \'إضافة\' (لجميع أنواع المنشورات الهرمية) بناءً على أذونات ارتباط المستخدم','CMS Page Tree View plugin: hide \'add\' links (for pages) based on user\'s page association permissions'=>'مكون إضافي لعرض شجرة صفحات CMS: إخفاء روابط \'إضافة\' (للصفحات) بناءً على أذونات ارتباط الصفحة للمستخدم','CMS Page Tree View plugin: hide \'add\' links (for specified hierarchical post type) based on user\'s association permissions'=>'مكون إضافي لعرض شجرة صفحات CMS: إخفاء روابط \'إضافة\' (لنمط منشور هرمي محدد) بناءً على أذونات ارتباط المستخدم','Prevent Permission from filtering the Nested Pages listing at all'=>'منع الصلاحيات من تصفية قائمة الصفحات المتداخلة تمامًا','Force Permissions to filter the Nested Pages listing'=>'فرض الصلاحيات لتصفية قائمة الصفحات المتداخلة','Comma-separated list of roles that are allowed to Quick Edit nested pages'=>'قائمة مفصولة بفواصل من الأدوار المسموح لها بتعديل الصفحات المتداخلة بسرعة','Comma-separated list of roles that are allowed to use the Context Menu'=>'قائمة مفصولة بفواصل من الأدوار المسموح لها باستخدام قائمة السياق','Never allow unfiltered users to use the Context Menu, even if they have pp_force_quick_edit capability'=>'لا تسمح أبدًا للمستخدمين غير المفلترين باستخدام قائمة السياق، حتى لو كانت لديهم قدرة pp_force_quick_edit','Disable Add Child link unless user is unfiltered (Administrator or has pp_nested_pages_unfiltered capability)'=>'قم بتعطيل رابط إضافة طفل إلا إذا كان المستخدم غير مفلتر (مدير أو لديه قدرة pp_nested_pages_unfiltered)','Disable Add Child Page link unless user is unfiltered'=>'تعطيل رابط إضافة صفحة طفل إلا إذا كان المستخدم غير مصفّى','Disable Insert Page Before link unless user is unfiltered'=>'تعطيل رابط إدراج صفحة قبل إلا إذا كان المستخدم غير مصفّى','Disable Insert Page After link unless user is unfiltered'=>'تعطيل رابط إدراج صفحة بعد إلا إذا كان المستخدم غير مصفّى','Disable Push to Top link unless user is unfiltered'=>'تعطيل رابط الدفع إلى الأعلى إلا إذا كان المستخدم غير مصفّى','Disable Push to Bottom link unless user is unfiltered'=>'تعطيل رابط الدفع إلى الأسفل إلا إذا كان المستخدم غير مصفّى','Disable Clone link unless user is unfiltered'=>'تعطيل رابط الاستنساخ إلا إذا كان المستخدم غير مصفّى','License'=>'ترخيص','License Key'=>'مفتاح الترخيص','Version'=>'الإصدار','settings'=>'الإعدادات','Key Expired'=>'مفتاح منتهي الصلاحية','Deactivate Key'=>'تعطيل المفتاح','Key Activated'=>'المفتاح مفعل','(please enter publishpress.com key)'=>'يرجى إدخال مفتاح publishpress.com','Activate Key'=>'تفعيل المفتاح','Note: Renewal does not require deactivation. If you do deactivate, re-entry of the license key will be required.'=>'ملاحظة: التجديد لا يتطلب إلغاء التنشيط. إذا قمت بإلغاء التنشيط، سيكون من الضروري إدخال مفتاح الترخيص مرة أخرى.','Your license key has expired. For continued priority support, %1$splease renew%2$s.'=>'مفتاح الترخيص الخاص بك قد انتهت صلاحيته. للحصول على دعم ذي أولوية مستمرة، %1$sيرجى تجديده%2$s.','Your license key will expire today. For updates and priority support, %1$splease renew%2$s.'=>'مفتاح الترخيص الخاص بك سينتهي اليوم. للحصول على التحديثات ودعم ذي أولوية، %1$sيرجى تجديده%2$s.','Your license key (for plugin updates) will expire in %1$d day(s). For updates and priority support, %2$splease renew%3$s.'=>'مفتاح الترخيص الخاص بك (لتحديثات الإضافات) سينتهي في %1$d يوم(أيام). للحصول على التحديثات ودعم ذي أولوية، %2$sيرجى تجديده%3$s.','For updates to Permissions Pro, activate your %1$sPublishPress license key%2$s.'=>'لتحديثات Permissions Pro، قم بتنشيط %1$sمفتاح ترخيص PublishPress الخاص بك%2$s.','reload module info'=>'إعادة تحميل معلومات الوحدة','Permissions Pro Version: %1$s %2$s'=>'إصدار برو من الأذونات: %1$s %2$s','view %s&nbsp;details'=>'عرض تفاصيل %s&nbsp;','update check / install'=>'التحقق من التحديث / التثبيت','Database Schema Version: %s'=>'إصدار مخطط قاعدة البيانات: %s','Installation History'=>'تاريخ التثبيت','%s (previous install)'=>'%s (التثبيت السابق)','WordPress Version: %s'=>'إصدار ووردبريس: %s','PHP Version: %s'=>'إصدار PHP: %s','The request could not be processed due to a connection failure.'=>'لم يتمكن النظام من معالجة الطلب بسبب فشل الاتصال.','Please enter the license key shown on your order receipt.'=>'يرجى إدخال مفتاح الترخيص الموضح في إيصال الطلب الخاص بك.','An unidentified error occurred.'=>'حدث خطأ غير محدد.','The key has been deactivated.'=>'تم إلغاء تنشيط المفتاح.','The key has been activated.'=>'تم تنشيط المفتاح.','The key has expired.'=>'انتهت صلاحية المفتاح.','The key is invalid.'=>'المفتاح غير صالح.','The key could not be activated. Please retry.'=>'لم يتمكن من تنشيط المفتاح. يرجى المحاولة مرة أخرى.','Circle Membership'=>'عضوية الدائرة','Viewing'=>'عرض','Editing'=>'تحرير','%s is limited to circle authors only, for these post types:'=>'%s مقتصر على مؤلفي الدائرة فقط، لأنواع المشاركات هذه:','Circle Activation'=>'تنشيط الدائرة','Visibility Circle'=>'دائرة الرؤية','Editorial Circle'=>'دائرة التحرير','Users in this group will only be able to view posts that were authored by other users in this group.'=>'يمكن للمستخدمين في هذه المجموعة عرض المشاركات التي كتبها مستخدمون آخرون في هذه المجموعة فقط.','Users in this group will only be able to edit posts that were authored by other users in this group.'=>'يمكن للمستخدمين في هذه المجموعة تعديل المشاركات التي كتبها مستخدمون آخرون في هذه المجموعة فقط.','Normal capability requirements will also be enforced.'=>'سوف يتم تطبيق متطلبات القدرة العادية أيضًا.','This group is a %s'=>'هذه المجموعة هي %s','Circles cannot be enforced on roles with %s capabilities.'=>'لا يمكن تطبيق الدوائر على الأدوار ذات قدرات %s.','%s%s restrictions%s do not apply to this role. %s'=>'%s%s القيود%s لا تنطبق على هذا الدور. %s','Apply limitation for post types:'=>'تطبيق القيود على أنواع المنشورات:','Users may be excused from Circle restrictions by adding the %1$s or %2$s capability to their role.'=>'يمكن إعفاء المستخدمين من قيود الدائرة عن طريق إضافة القدرة %1$s أو %2$s إلى دورهم.','Circle Type'=>'نوع الدائرة','Visibility'=>'الرؤية','Editorial'=>'تحريري','Access Circle restrictions apply to revisions'=>'تنطبق قيود دائرة الوصول على التعديلات','Create Topics in'=>'إنشاء مواضيع في','Topic Creation'=>'إنشاء موضوع','Create Topic'=>'إنشاء موضوع','Submit Replies in'=>'إرسال ردود في','Reply Submission'=>'تقديم الردود','Submit Reply'=>'إرسال رد','Show more details'=>'عرض المزيد من التفاصيل','BuddyPress Group'=>'مجموعة BuddyPress','BP Permission Group'=>'مجموعة أذونات BP','BP Permission Groups'=>'مجموعة أذونات BP','Manage'=>'إدارة','BuddyPress Groups'=>'مجموعات BuddyPress','Page creation was blocked because you are not allowed to select that parent page.'=>'لا يُسمح لك باختيار تلك الصفحة الأبوية.','Back to Dashboard'=>'العودة إلى لوحة التحكم','Permission Denied'=>'تم رفض الإذن','You are not allowed to select that parent page.'=>'لا يُسمح لك باختيار تلك الصفحة الأبوية.','Network Groups'=>'مجموعات الشبكة','Network Group'=>'مجموعة الشبكة','Teaser text'=>'نص ترويجي','Network'=>'شبكة','Groups'=>'مجموعات','Forum Teaser'=>'نص ترويجي للمنتدى','Network-wide groups'=>'مجموعات على مستوى الشبكة','Teaser Topics'=>'مواضيع ترويجية','Hide Topic / Reply Author Link'=>'إخفاء رابط مؤلف الموضوع / الرد','Compatibility Pack'=>'حزمة التوافق','Topic Teaser Text (%s):'=>'نص ترويجي للموضوع (%s):','Reply Teaser Text (%s):'=>'نص ترويجي للرد (%s):','First Reply'=>'أول رد','Other Replies'=>'ردود أخرى','Not Logged In'=>'غير متصل','Logged In Users'=>'المستخدمون المسجلون','Insert a login form by using %s[login_form]%s shortcode.'=>'أدخل نموذج تسجيل دخول باستخدام %s[login_form]%s كود قصير.','Hide Topics and Replies'=>'إخفاء المواضيع والردود','Tease Topics and Replies'=>'ترويج المواضيع والردود','Show Topics, Tease Replies'=>'عرض المواضيع، ترويج الردود','The single forum teaser may be customized by STYLESHEETPATH/press-permit/teaser-content-forum.php'=>'يمكن تخصيص معاينة المنتدى الفردية من خلال STYLESHEETPATH/press-permit/teaser-content-forum.php','[This topic requires additional permissions or membership.]'=>'[تتطلب هذه الموضوعات أذونات إضافية أو عضوية.]','[...]'=>'[...]','[This topic requires site login.]'=>'[تتطلب هذه الموضوعات تسجيل الدخول إلى الموقع.]','[login required]'=>'[تسجيل الدخول مطلوب]','[This reply requires site login.]'=>'[تتطلب هذه الردود تسجيل الدخول إلى الموقع.]','File Access'=>'الوصول إلى الملفات','File Access Reset Key:'=>'مفتاح إعادة تعيين وصول الملف:','Small Thumbnails Unfiltered'=>'صور مصغرة صغيرة غير مصفاة','Make Unattached Files Private'=>'اجعل الملفات غير المرتبطة خاصة','Make Attached Files Private'=>'اجعل الملفات المرفقة خاصة','%1$sNote%2$s: Direct access to uploaded file attachments cannot be filtered because mod_rewrite is not enabled on your server.'=>'%1$sملاحظة%2$s: لا يمكن تصفية الوصول المباشر إلى مرفقات الملفات المرفوعة لأن mod_rewrite غير مفعل على خادمك.','%1$sNote%2$s: Direct access to uploaded file attachments will not be filtered due to your nonstandard UPLOADS path.'=>'%1$sملاحظة%2$s: لن يتم تصفية الوصول المباشر إلى مرفقات الملفات المرفوعة بسبب مسار UPLOADS غير القياسي لديك.','%1$sNote%2$s: Direct access to uploaded file attachments cannot be filtered because WordPress permalinks are set to default.'=>'%1$sملاحظة%2$s: لا يمكن تصفية الوصول المباشر إلى مرفقات الملفات المرفوعة لأن الروابط الدائمة في ووردبريس تم تعيينها على الوضع الافتراضي.','show required rules'=>'عرض القواعد المطلوبة','Copy'=>'نسخ','Copied!'=>'تم النسخ!','Regenerate Access File'=>'إعادة توليد ملف الوصول','Attachments Utility'=>'أداة المرفقات','For Nginx integration, see %spublishpress.com documentation%s.'=>'لدمج Nginx، راجع وثائق %spublishpress.com%s.','Back to Permissions Settings'=>'العودة إلى إعدادات الأذونات','File Access for Files Uploaded via FTP'=>'وصول الملفات للملفات التي تم تحميلها عبر FTP','Find Files Uploaded via FTP'=>'البحث عن الملفات التي تم تحميلها عبر FTP','The network attachment scan has been queued and will continue in the background via WP-Cron.'=>'تم وضع فحص المرفقات الشبكية في قائمة الانتظار وسيستمر في الخلفية عبر WP-Cron.','A network attachment scan is already in progress or could not be scheduled.'=>'يتم الآن إجراء فحص للمرفقات الشبكية أو لم يكن من الممكن جدولته.','Site Configuration Requirements'=>'متطلبات تكوين الموقع','For proper access control of direct file URLs, your site must meet these requirements:'=>'للحصول على التحكم المناسب في الوصول إلى عناوين الملفات المباشرة، يجب أن يلبي موقعك هذه المتطلبات:','Automated Processing'=>'المعالجة الآلية','Utility Endpoint URL:'=>'عنوان URL لنقطة النهاية للأداة:','Copy URL'=>'نسخ عنوان URL','Go to Settings'=>'الذهاب إلى الإعدادات','RUNNING'=>'يتم التشغيل','Operation complete'=>'العملية مكتملة','Scan Again'=>'امسح مرة أخرى','%1$s (%2$s - %3$s)'=>'%1$s (%2$s - %3$s)','Role selection is required for %s. Please select at least one role.'=>'اختيار الدور مطلوب لـ %s. يرجى اختيار دور واحد على الأقل.','You seem to be using a Team / Staff plugin. To synchronize posts to users and give them editing permission, go to %1$sPermissions > Settings > Sync Posts%2$s'=>'يبدو أنك تستخدم مكونًا إضافيًا للفريق / الموظفين. لمزامنة المشاركات مع المستخدمين ومنحهم إذن التعديل، انتقل إلى %1$sالأذونات > الإعدادات > مزامنة المشاركات%2$s','User Posts'=>'منشورات المستخدمين','Synchronize Posts'=>'مزامنة المنشورات','Create Posts for Users'=>'إنشاء منشورات للمستخدمين','Grant Author Permissions'=>'منح أذونات المؤلف','Post Types'=>'أنواع المنشورات','Match Post Field'=>'مطابقة حقل المنشور','Match User Field'=>'مطابقة حقل المستخدم','User Role'=>'دور المستخدم','Parent Post'=>'المنشور الرئيسي','Quantity'=>'الكمية','Post Status'=>'حالة المنشور','Post Title'=>'عنوان المنشور','Post slug'=>'رابط المنشور','User Display Name'=>'اسم العرض للمستخدم','User email'=>'البريد الإلكتروني للمستخدم','User login'=>'تسجيل دخول المستخدم','User nicename'=>'اسم المستخدم','User Posts Created:'=>'تم إنشاء منشورات المستخدمين:','Post Type'=>'نوع المنشور','Select where posts will be created for users.'=>'اختر المكان الذي سيتم فيه إنشاء المنشورات للمستخدمين.','New Users'=>'المستخدمون الجدد','Create posts for new users.'=>'إنشاء منشورات للمستخدمين الجدد.','Current Users'=>'المستخدمون الحاليون','Create posts for existing users.'=>'إنشاء منشورات للمستخدمين الحاليين.','Role'=>'الدور','Create posts for users in these roles.'=>'إنشاء منشورات للمستخدمين في هذه الأدوار.','Set the number of posts to create for each user.'=>'حدد عدد المنشورات التي سيتم إنشاؤها لكل مستخدم.','Status'=>'الحالة','Set the status for created posts.'=>'حدد الحالة للمنشورات التي تم إنشاؤها.','No post types are enabled for user pages.'=>'لا توجد أنواع منشورات مفعلّة لصفحات المستخدمين.','Go to Permissions Settings'=>'اذهب إلى إعدادات الأذونات','Click to expand/collapse advanced settings'=>'انقر للتوسيع/الطي للإعدادات المتقدمة','(All Roles)'=>'(جميع الأدوار)','Published'=>'منشور منشور','Draft'=>'مسودة','Pending Review'=>'قيد المراجعة','Private'=>'خاص','Avoid Creating Duplicates'=>'تجنب إنشاء تكرارات','This setting can prevent the creation of duplicate posts for a user. If the selected fields are a match, a new post will not be created.'=>'يمكن أن تمنع هذه الإعدادات إنشاء مشاركات مكررة لمستخدم. إذا كانت الحقول المحددة متطابقة، فلن يتم إنشاء مشاركة جديدة.','Post Match Field'=>'حقل تطابق المنشور','Choose which post field to match with users.'=>'اختر الحقل الذي يتطابق مع المستخدمين.','(other)'=>'(أخرى)','select...'=>'اختر...','cancel'=>'إلغاء','User Match Field'=>'حقل تطابق المستخدم','Select which user field to match with posts.'=>'اختر أي حقل مستخدم يتطابق مع المنشورات.','Available Template Parameters'=>'معلمات القالب المتاحة','You can use these placeholders in the User Match Field to create custom templates:'=>'يمكنك استخدام هذه العناصر النائبة في حقل تطابق المستخدم لإنشاء قوالب مخصصة:','Examples:'=>'أمثلة:','Additional Field'=>'حقل إضافي','Additional configuration options for post creation.'=>'خيارات إعداد إضافية لإنشاء المنشورات.','Parent Post ID'=>'معرّف المنشور الرئيسي','Specify the Post ID of a parent post for hierarchical post types.'=>'حدد معرّف المنشور للمنشور الرئيسي لأنواع المنشورات الهرمية.','Enter parent post ID (0 for no parent)'=>'أدخل معرّف المنشور الرئيسي (0 لعدم وجود منشور رئيسي)','Validation Errors in User Posts Settings:'=>'أخطاء التحقق في إعدادات منشورات المستخدم:','Please fix these errors and try again.'=>'يرجى إصلاح هذه الأخطاء والمحاولة مرة أخرى.','%s: Skipping because no roles are selected'=>'%s: يتم التخطي لأنه لم يتم اختيار أي أدوار','%s: Enabled PressPermit filtering (Core > Filtered Post Types)'=>'%s: تم تمكين تصفية PressPermit (النواة > أنواع المنشورات المفلترة)','%1$s: Assigned extra %2$s Author role to %3$s role'=>'%1$s: تم تعيين دور مؤلف إضافي %2$s إلى دور %3$s','Ambiguous %1$s match (%2$s)'=>'تطابق غامض %1$s (%2$s)','Ambiguous user match for %1$s (%2$s, post id %3$s'=>'مطابقة مستخدم غامضة لـ %1$s (%2$s، معرف المشاركة %3$s','Ambiguous user match for %1$s (%2$s, $post id %3$s)'=>'مطابقة مستخدم غامضة لـ %1$s (%2$s، معرف المشاركة %3$s)','Ambiguous user match for %1$s (%2$s)'=>'مطابقة مستخدم غامضة لـ %1$s (%2$s)','%1$s: %2$s posts created.'=>'%1$s: تم إنشاء %2$s منشورات.','%1$s: %2$s posts updated.'=>'%1$s: تم تحديث %2$s منشورات.','All Roles'=>'جميع الأدوار','%1$s: Done for %2$s.'=>'%1$s: تم الانتهاء من %2$s.','%s: Done.'=>'%s: تم الانتهاء.']];